node -e "
const ExcelJS = require('exceljs');

(async () => {
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Travel');

  // Write 129 in row 43, column 7 (cell G43)
  sheet.getRow(43).getCell(7).value = 129;

  await workbook.xlsx.writeFile('data/travel_expenses.xlsx');
  console.log('Done! Wrote 129 to Travel!G43');

  // Verify
  const wb2 = new ExcelJS.Workbook();
  await wb2.xlsx.readFile('data/travel_expenses.xlsx');
  const ws = wb2.getWorksheet('Travel');
  console.log('Verification - Travel!G43 =', ws.getRow(43).getCell(7).value);
})();
"
